// Deja el lote en la forma que espera el CRM y descarta lo que no procede.
// Los mensajes del propio bot se excluyen para no reprocesar sus respuestas.
const mensajes = [];
for (const item of $input.all()) {
  const m = item.json;
  if (!m || !m.id || !m.channel_id) continue;
  if (m.author && m.author.bot === true) continue;
  const content = typeof m.content === 'string' ? m.content.trim() : '';
  if (content.length === 0) continue;
  mensajes.push({
    messageId: String(m.id),
    channelId: String(m.channel_id),
    authorId: m.author && m.author.id ? String(m.author.id) : undefined,
    authorUsername: m.author && m.author.username ? String(m.author.username) : undefined,
    content,
    timestamp: m.timestamp ? String(m.timestamp) : undefined,
  });
}

// Sin nada que enviar, no se llama al CRM.
if (mensajes.length === 0) return [];
return [{ json: { messages: mensajes.slice(0, 25) } }];

// Convierte el resultado del CRM en una reacción idempotente sobre el mensaje original.
// 👀 = leído y pendiente de revisión; ⚠️ = guardado pero incompleto;
// ✅ = trato ya aprobado; 🚫 = rechazado; ❌ = fallo, se reintentará.
const outcomes = Array.isArray($json.outcomes) ? $json.outcomes : [];
const channelId = String($('Config').first().json.channelId);
const emojiByStatus = {
  missing_info: '⚠️',
  pending_review: '👀',
  created: '✅',
  rejected: '🚫',
};

return outcomes.flatMap((outcome) => {
  if (!outcome || outcome.result === 'ignored') return [];
  const emoji = outcome.result === 'failed'
    ? '❌'
    : (emojiByStatus[outcome.status] || '👀');
  return [{
    json: {
      messageId: String(outcome.messageId),
      channelId,
      emoji,
      result: outcome.result,
      status: outcome.status || null,
      draftId: outcome.draftId || null,
    },
  }];
});
